CREATE TABLE "DiscountRule" ("id" TEXT NOT NULL, "shop" TEXT NOT NULL, "title" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "priority" INTEGER NOT NULL DEFAULT 0, "targetType" TEXT NOT NULL, "internalNotes" TEXT NOT NULL DEFAULT '', "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DiscountRule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DiscountTarget" ("id" TEXT NOT NULL, "shopifyId" TEXT NOT NULL, "label" TEXT NOT NULL DEFAULT '', "ruleId" TEXT NOT NULL, CONSTRAINT "DiscountTarget_pkey" PRIMARY KEY ("id"), CONSTRAINT "DiscountTarget_ruleId_fkey" FOREIGN KEY ("ruleId") REFERENCES "DiscountRule" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "DiscountTier" ("id" TEXT NOT NULL, "minimum" INTEGER NOT NULL, "maximum" INTEGER, "title" TEXT NOT NULL DEFAULT '', "discountType" TEXT NOT NULL, "discountValue" DECIMAL(65,30), "message" TEXT NOT NULL DEFAULT '', "ruleId" TEXT NOT NULL, CONSTRAINT "DiscountTier_pkey" PRIMARY KEY ("id"), CONSTRAINT "DiscountTier_ruleId_fkey" FOREIGN KEY ("ruleId") REFERENCES "DiscountRule" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "DiscountRule_shop_enabled_priority_idx" ON "DiscountRule"("shop", "enabled", "priority");
CREATE UNIQUE INDEX "DiscountTarget_ruleId_shopifyId_key" ON "DiscountTarget"("ruleId", "shopifyId");
CREATE UNIQUE INDEX "DiscountTier_ruleId_minimum_key" ON "DiscountTier"("ruleId", "minimum");
CREATE INDEX "DiscountTier_ruleId_minimum_idx" ON "DiscountTier"("ruleId", "minimum");
